From 5869de18f73020f033d8ecd9d8b359291b63dafa Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sun, 22 Nov 2026 16:33:27 +0100
Subject: [PATCH] wayland: keep the last frame on screen until the lock screen
 shows
MIME-Version: 1.0
Content-Type: text/plain; charset=UTF-8
Content-Transfer-Encoding: 8bit

Locking turned the screen black until the greeter had drawn its first
frame, up to a second later. Pause the outputs instead until a lock
screen window appears, the session unlocks or the system sleeps (≤2 s).

BUG: 520995
---
 src/wayland_server.cpp | 46 ++++++++++++++++++++++++++++++++++++++++++
 src/wayland_server.h   |  7 +++++++
 2 files changed, 53 insertions(+)

diff --git a/src/wayland_server.cpp b/src/wayland_server.cpp
index e83c6adcb8..75c738be04 100644
--- a/src/wayland_server.cpp
+++ b/src/wayland_server.cpp
@@ -17,6 +17,7 @@
 #include "core/gpumanager.h"
 #include "core/outputbackend.h"
 #include "core/renderdevice.h"
+#include "core/renderloop.h"
 #include "core/session.h"
 #include "idle_inhibition.h"
 #include "inputpanelv1integration.h"
@@ -642,6 +643,25 @@ void WaylandServer::initScreenLocker()

     connect(screenLockerApp, &ScreenLocker::KSldApp::lockStateChanged, this, &WaylandServer::lockStateChanged);

+    // Keep the last unlocked frame on screen until the greeter can show itself instead of a black screen
+    m_greeterHoldTimer.setSingleShot(true);
+    m_greeterHoldTimer.setInterval(std::chrono::seconds(2));
+    connect(&m_greeterHoldTimer, &QTimer::timeout, this, &WaylandServer::releaseFramesForGreeter);
+    connect(screenLockerApp, &ScreenLocker::KSldApp::locked, this, &WaylandServer::holdFramesForGreeter);
+    connect(screenLockerApp, &ScreenLocker::KSldApp::unlocked, this, &WaylandServer::releaseFramesForGreeter);
+    connect(this, &WaylandServer::windowAdded, this, [this](Window *window) {
+        if (window->isLockScreen()) {
+            releaseFramesForGreeter();
+        }
+    });
+    connect(kwinApp()->session(), &Session::aboutToSleep, this, [this]() {
+        m_sleepPending = true;
+        releaseFramesForGreeter();
+    });
+    connect(kwinApp()->session(), &Session::awoke, this, [this]() {
+        m_sleepPending = false;
+    });
+
     ScreenLocker::KSldApp::self()->initialize();

     if (kwinApp()->initiallyLocked()) {
@@ -650,6 +670,32 @@ void WaylandServer::initScreenLocker()
 #endif
 }

+void WaylandServer::holdFramesForGreeter()
+{
+    if (m_sleepPending || m_greeterHoldTimer.isActive()) {
+        return;
+    }
+    const auto outputs = kwinApp()->outputBackend()->outputs();
+    for (BackendOutput *output : outputs) {
+        if (output->isEnabled()) {
+            output->renderLoop()->inhibit();
+            m_greeterHeldRenderLoops.append(output->renderLoop());
+        }
+    }
+    m_greeterHoldTimer.start();
+}
+
+void WaylandServer::releaseFramesForGreeter()
+{
+    m_greeterHoldTimer.stop();
+    const auto renderLoops = std::exchange(m_greeterHeldRenderLoops, {});
+    for (RenderLoop *renderLoop : renderLoops) {
+        if (renderLoop) {
+            renderLoop->uninhibit();
+        }
+    }
+}
+
 WaylandServer::SocketPairConnection WaylandServer::createConnection()
 {
     SocketPairConnection ret;
diff --git a/src/wayland_server.h b/src/wayland_server.h
index d99dac47a4..2405501bc8 100644
--- a/src/wayland_server.h
+++ b/src/wayland_server.h
@@ -13,6 +13,7 @@
 #include <QObject>
 #include <QPointer>
 #include <QSet>
+#include <QTimer>

 namespace KWin
 {
@@ -70,6 +71,7 @@ class FifoManagerV1;
 class SinglePixelBufferManagerV1;
 class ColorRepresentationManagerV1;
 class BackendOutput;
+class RenderLoop;
 class ExtBackgroundEffectManagerV1;
 class CommitTimingManagerV1;

@@ -238,6 +240,8 @@ Q_SIGNALS:
 private:
     int createScreenLockerConnection();
     void initScreenLocker();
+    void holdFramesForGreeter();
+    void releaseFramesForGreeter();
     void registerXdgGenericWindow(Window *window);
     void registerXdgToplevelWindow(XdgToplevelWindow *window);
     void registerXdgPopupWindow(XdgPopupWindow *window);
@@ -270,6 +274,9 @@ private:
     InputMethodV1Interface *m_inputMethod = nullptr;
     QPointer<ClientConnection> m_inputMethodServerConnection;
     QPointer<ClientConnection> m_screenLockerClientConnection;
+    QList<QPointer<RenderLoop>> m_greeterHeldRenderLoops;
+    QTimer m_greeterHoldTimer;
+    bool m_sleepPending = false;
     XdgForeignV2Interface *m_XdgForeign = nullptr;
     XdgActivationV1Integration *m_xdgActivationIntegration = nullptr;
 #if KWIN_BUILD_X11
